import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.launch

sealed class Screen {
  object PatientList : Screen()
  data class PatientDetail(val patient: PatientItem) : Screen()
  data class NewVisitForm(val patient: PatientItem) : Screen()
}

class MainActivity : ComponentActivity() {
  private val viewModel: AncViewModel by viewModels()

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent {
      MaterialTheme {
        Surface(modifier = Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
          AncAppNavHost(viewModel)
        }
      }
    }
  }
}

@Composable
fun AncAppNavHost(viewModel: AncViewModel) {
  var currentScreen by remember { mutableStateOf<Screen>(Screen.PatientList) }

  when (val screen = currentScreen) {
    is Screen.PatientList -> {
      PatientListScreen(
        viewModel = viewModel,
        onPatientClick = { patient ->
          viewModel.selectPatient(patient)
          currentScreen = Screen.PatientDetail(patient)
        }
      )
    }
    is Screen.PatientDetail -> {
      BackHandler {
        currentScreen = Screen.PatientList
      }
      PatientDetailScreen(
        viewModel = viewModel,
        patient = screen.patient,
        onBack = { currentScreen = Screen.PatientList },
        onRecordNewVisit = {
          viewModel.loadQuestionnaire()
          currentScreen = Screen.NewVisitForm(screen.patient)
        }
      )
    }
    is Screen.NewVisitForm -> {
      BackHandler {
        currentScreen = Screen.PatientDetail(screen.patient)
      }
      NewVisitFormScreen(
        viewModel = viewModel,
        patient = screen.patient,
        onClose = {
          currentScreen = Screen.PatientDetail(screen.patient)
        }
      )
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun PatientListScreen(
  viewModel: AncViewModel,
  onPatientClick: (PatientItem) -> Unit
) {
  val patients by viewModel.patients.collectAsState()
  val syncStatus by viewModel.syncStatus.collectAsState()
  val isLoading by viewModel.isLoading.collectAsState()

  Scaffold(
    topBar = {
      TopAppBar(
        title = {
          Column {
            Text("ANC Register", fontWeight = FontWeight.Bold)
            Text(
              text = syncStatus ?: "",
              style = MaterialTheme.typography.bodySmall,
              color = MaterialTheme.colorScheme.onSurfaceVariant
            )
          }
        },
        actions = {
          IconButton(onClick = { viewModel.syncNow() }) {
            Icon(Icons.Default.Refresh, contentDescription = "Sync now")
          }
        }
      )
    }
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues)
    ) {
