@Composable
fun VisitCard(visit: VisitItem) {
  Card(
    modifier = Modifier.fillMaxWidth(),
    elevation = CardDefaults.cardElevation(defaultElevation = 1.dp)
  ) {
    Column(modifier = Modifier.padding(14.dp)) {
      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween
      ) {
        Text(
          text = "Visit Date: ${visit.date ?: "Unknown"}",
          style = MaterialTheme.typography.bodyMedium,
          fontWeight = FontWeight.Bold
        )
      }

      Spacer(modifier = Modifier.height(6.dp))

      Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween
      ) {
        Text("Weight: ${visit.weightKg ?: "--"}", style = MaterialTheme.typography.bodyMedium)
        Text("BP: ${visit.bloodPressure ?: "--"}", style = MaterialTheme.typography.bodyMedium)
        if (visit.hemoglobin != null) {
          Text("Hb: ${visit.hemoglobin}", style = MaterialTheme.typography.bodyMedium)
        }
      }

      if (visit.dangerSigns.isNotEmpty()) {
        Spacer(modifier = Modifier.height(6.dp))
        Text(
          text = "Danger signs: ${visit.dangerSigns.joinToString(", ")}",
          style = MaterialTheme.typography.bodySmall,
          color = MaterialTheme.colorScheme.error,
          fontWeight = FontWeight.Medium
        )
      }

      if (!visit.notes.isNullOrBlank()) {
        Spacer(modifier = Modifier.height(4.dp))
        Text(
          text = "Notes: ${visit.notes}",
          style = MaterialTheme.typography.bodySmall,
          color = MaterialTheme.colorScheme.onSurfaceVariant
        )
      }
    }
  }
}

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun NewVisitFormScreen(
  viewModel: AncViewModel,
  patient: PatientItem,
  onClose: () -> Unit
) {
  val questionnaireJson by viewModel.questionnaireJson.collectAsState()
  val scope = rememberCoroutineScope()
  var isSaving by remember { mutableStateOf(false) }
  var saveError by remember { mutableStateOf<String?>(null) }

  Scaffold(
    topBar = {
      TopAppBar(
        title = { Text("New ANC Visit - ${patient.name}") },
        navigationIcon = {
          IconButton(onClick = onClose) {
            Icon(Icons.AutoMirrored.Filled.ArrowBack, contentDescription = "Cancel")
          }
        }
      )
    }
  ) { paddingValues ->
    Box(
      modifier = Modifier
        .fillMaxSize()
        .padding(paddingValues)
    ) {
      val jsonStr = questionnaireJson
      if (jsonStr == null) {
        CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
      } else {
        Questionnaire(
          questionnaireJson = jsonStr,
          config = QuestionnaireConfig(
            showSubmitButton = true,
            showCancelButton = true,
            submitButtonText = "Save Visit"
          ),
          onSubmit = { getResponse ->
            scope.launch {
              try {
                isSaving = true
                val response: QuestionnaireResponse = getResponse()
                viewModel.saveAncVisit(patient.id, response)
                isSaving = false
                onClose()
              } catch (e: CancellationException) {
                // Answer validation failed, questionnaire displays errors internally
                isSaving = false
              } catch (e: Exception) {
                isSaving = false
                saveError = e.message ?: "Failed to save visit"
              }
            }
          },
          onCancel = onClose
        )
      }

      if (isSaving) {
        Surface(
          modifier = Modifier.fillMaxSize(),
          color = Color.Black.copy(alpha = 0.3f)
        ) {
          Box(contentAlignment = Alignment.Center) {
            CircularProgressIndicator()
          }
        }
      }

      saveError?.let { err ->
        AlertDialog(
          onDismissRequest = { saveError = null },
          title = { Text("Error") },
          text = { Text(err) },
          confirmButton = {
            Button(onClick = { saveError = null }) {
              Text("OK")
            }
          }
        )
      }
    }
  }
}

